const fold = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/æ/g, 'ae')
  .replace(/œ/g, 'oe').replace(/['’‘]/g, '').replace(/[^a-z0-9+:-]+/g, ' ').trim();
